{
  "themes": [
    {
      "cluster": 12,
      "name": "Pre‑Order and Delivery Delays",
      "description": "Customers report pre‑ordered books arriving late, being out of stock, or delivered to the wrong address."
    },
    {
      "cluster": 13,
      "name": "Unanswered Direct Messages",
      "description": "Users mention sending DMs or asking for help but receiving no response."
    },
    {
      "cluster": 14,
      "name": "Holiday (Diwali) Delivery Failures",
      "description": "Customers complain that orders were not delivered in time for Diwali, causing disappointment."
    },
    {
      "cluster": 15,
      "name": "Order Status and Cancellation Issues",
      "description": "Customers seek updates on order IDs, request cancellations, or report canceled orders without compensation."
    },
    {
      "cluster": 16,
      "name": "Poor Shipping and Customer Service",
      "description": "Users describe broken items, out‑of‑stock notifications after long waits, and unhelpful courier or support staff."
    },
    {
      "cluster": 17,
      "name": "Pricing Discrepancies and Discounts",
      "description": "Customers notice mismatched MRP vs. displayed price, confusing discount calculations, and flash‑sale inconsistencies."
    },
    {
      "cluster": 18,
      "name": "Account Hacking and Phishing Concerns",
      "description": "Users report suspected account hacks, fraudulent emails, and inability to log in due to security issues."
    },
    {
      "cluster": 19,
      "name": "Locked Accounts and Login Failures",
      "description": "Customers are locked out of their accounts, cannot reset passwords, or encounter broken sign‑up pages."
    },
    {
      "cluster": 20,
      "name": "Fake Reviews and Warranty Confusion",
      "description": "Customers receive unsolicited review emails, question warranty offers, and express frustration over misleading product claims."
    },
    {
      "cluster": 21,
      "name": "Negative Experiences Specific to India",
      "description": "Indian users cite poor customer service, undelivered orders, and perceived cheating by the platform."
    },
    {
      "cluster": 22,
      "name": "Broken Links and Site Errors",
      "description": "Users encounter error pages, broken URLs, and inability to perform actions like adding balance or selecting sizes."
    },
    {
      "cluster": 23,
      "name": "Late or Lost Deliveries",
      "description": "Customers complain about two‑day shipping not being honored, parcels left unattended, and repeated lost packages."
    }
  ]
}
